/** Native witness bodies must keep their native inner predicates even when their caller is an IR kernel. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeNestedExistsModeQuoteTest {

	private static final int INPUT_ROWS = 4;
	private static final int FLAG_ROWS = 1;
	private static final long ROOT = iri(1), EDGE = iri(2), FLAG = iri(3), GRAPH = iri(4);
	private static final long OUTER = iri(5), OTHER = iri(6), VALUE = iri(7);
	private final Map<String, String> previous = new LinkedHashMap<>();

	@BeforeEach
	void configurePhysicalRoute() {
		set(LmdbNativeKernelLowering.SCAN_SOURCES_PROPERTY, "true");
		set(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY, "true");
		set(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY, "false");
		set(LmdbNativeKernelLowering.ROW_EXISTS_PROPERTY, "true");
		set(LmdbNativeKernelInterpreter.ENABLED_PROPERTY, "true");
		set(SubplanMarkProbe.ENABLED_PROPERTY, "false");
		set("rdf4j.lmdb.membership.impl", "hash");
	}

	@AfterEach
	void restoreProperties() {
		previous.forEach((key, value) -> {
			if (value == null) {
				System.clearProperty(key);
			} else {
				System.setProperty(key, value);
			}
		});
	}

	@ParameterizedTest
	@CsvSource({ "false,1", "false,4", "true,1", "true,4" })
	void aNativeWitnessBodyCannotPriceItsInnerExistsAsADirectKernelProbe(boolean extension, int acceptedOrdinal) {
		CountingSource source = new CountingSource(acceptedOrdinal);
		RowState row = row(source);
		try {
			PatternPlan edge = pattern(source, 0, EDGE, 1, INPUT_ROWS);
			StatementPatternExistsFilter inner = new StatementPatternExistsFilter(source, Term.slot(1),
					Term.constant(FLAG), Term.constant(VALUE), Term.unbound(), ContextConstraint.UNRESTRICTED, false);
			assertThat(LmdbNativeKernelLowering.statementWitnessEligible(inner)).isTrue();
			assertThat(SlotPlan.assuredMask(edge) & 1L << 1).isEqualTo(1L << 1);
			SlotPlan filtered = new FilterPlan(edge, inner, 1L << 1);
			SlotPlan body = extension
					? new ExtensionPlan(filtered, new CopyBinding[] { CopyBinding.constant(2, VALUE) })
					: new UnionPlan(filtered, pattern(source, 0, OTHER, 1, 1D));
			ExistsFilter outer = new ExistsFilter(body);
			assertThat(outer.existsPlan).as("this wrapper executes the ordinary native subplan cursor").isNull();
			NativeBooleanFilter ordinary = new NativeBooleanFilter() {
				@Override
				public boolean accept(RowState ignored) {
					return false;
				}

				@Override
				public long batchReadMask() {
					return 0L;
				}
			};
			// The complete family is one native hook. Its nested subplan is not lowered a second time.
			NativeBooleanFilter condition = new BooleanCombinationFilter(outer, ordinary, false);
			SlotPlan input = new UnionPlan(outer(source, OUTER), outer(source, OTHER));
			assertNativeHookAdmission(new FilterPlan(input, condition, 1L), condition, row);
			assertThat(source.recordReads).isZero();
			assertThat(source.flagTests).isZero();

			row.slots[0] = ROOT;
			row.recomputeBoundMask();
			LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.kernelVector(
					new FilterPlan(SingletonPlan.INSTANCE, condition, 1L), row, row.boundMask(),
					Feature.INTERPRETED_ROW);
			assertThat(source.flagTests).as("pricing never evaluates membership").isZero();
			assertThat(condition.accept(row)).isTrue();
			assertThat(source.edgeReads).as("the native factor leaf builds all four input records before replay")
					.isEqualTo(INPUT_ROWS);
			assertThat(source.flagTests).as("each candidate really calls the inner native membership predicate")
					.isEqualTo(acceptedOrdinal);
			assertThat(source.closes).isEqualTo(source.opens);
			assertThat(row.slots[0]).isEqualTo(ROOT);
			System.out.printf("extension=%s actualInnerMembership=%d quotedMembership=%.3f high=%.3f%n",
					extension, source.flagTests, quote.expected(Feature.MEMBERSHIP_TEST),
					quote.high(Feature.MEMBERSHIP_TEST));
			assertThat(quote.high(Feature.MEMBERSHIP_TEST))
					.as("a native outer hook cannot make its inner native membership work disappear")
					.isGreaterThanOrEqualTo(source.flagTests);
		} finally {
			row.memoryScope.close();
		}
	}

	private static void assertNativeHookAdmission(FilterPlan plan, NativeBooleanFilter condition, RowState row) {
		try (LmdbNativeStrategyProposal<RowCursor> proposal = LmdbNativeKernelExecution.proposeRows(plan, row, null,
				true)) {
			assertThat(proposal).isNotNull();
			LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerRows(plan, row, null, false);
			assertThat(lowered).isNotNull();
			List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
			LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
			assertThat(nodes).anyMatch(LmdbNativeKernelIr.FilterValue.class::isInstance)
					.noneMatch(LmdbNativeKernelIr.Exists.class::isInstance);
			assertThat(lowered.bindings.filterHooks).singleElement()
					.satisfies(hook -> assertThat(hook.source.filter).isSameAs(condition));
			assertThat(lowered.kernel.resumable).isTrue();
			JaninoKernel kernel = LmdbNativeKernelInterpreter.forRows(lowered.kernel);
			assertThat(kernel).isNotNull();
			kernel.close();
		}
	}

	private static PatternPlan pattern(CountingSource source, int subject, long predicate, int object, double rows) {
		return new PatternPlan(Term.slot(subject), Term.constant(predicate), Term.slot(object), Term.constant(GRAPH),
				ContextConstraint.UNRESTRICTED, true, null, "", null, rows, source.indexAccessProfile());
	}

	private static PatternPlan outer(CountingSource source, long predicate) {
		return new PatternPlan(Term.slot(0), Term.constant(predicate), Term.constant(VALUE), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, 1D, source.indexAccessProfile());
	}

	private static long candidate(int ordinal) {
		return iri(100 + ordinal);
	}

	private static long iri(int ordinal) {
		return (long) ordinal << 7 | 1L << 1;
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}

	private static final class CountingSource implements NativeLmdbQuerySource {
		private final List<long[]> records = new ArrayList<>();
		private final IndexAccessProfile profile = coveringProfile(INPUT_ROWS + FLAG_ROWS + 2);
		int recordReads, edgeReads, flagOpens, flagTests, opens, closes;

		CountingSource(int acceptedOrdinal) {
			for (int i = 1; i <= INPUT_ROWS; i++) {
				records.add(new long[] { ROOT, EDGE, candidate(i), GRAPH });
			}
			// Four real candidates exist; exactly one has a matching FLAG at the chosen position.
			for (int i = 0; i < FLAG_ROWS; i++) {
				long subject = i == 0 && acceptedOrdinal > 0 ? candidate(acceptedOrdinal) : iri(2000 + i);
				records.add(new long[] { subject, FLAG, VALUE, GRAPH });
			}
			records.add(new long[] { ROOT, OUTER, VALUE, GRAPH });
			records.add(new long[] { ROOT, OTHER, VALUE, GRAPH });
		}

		@Override
		public IndexAccessProfile indexAccessProfile() {
			return profile;
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			return OptionalDouble.of(predicate == EDGE ? bySubject ? INPUT_ROWS : 1D
					: predicate == FLAG ? bySubject ? 1D : FLAG_ROWS : 1D);
		}

		@Override
		public RecordIterator statements(long subject, long predicate, long object, long context) {
			opens++;
			if (predicate == FLAG) {
				flagOpens++;
			}
			return new RecordIterator() {
				int index;
				boolean closed;

				@Override
				public long[] next() {
					while (index < records.size()) {
						long[] record = records.get(index++);
						if ((subject == UNKNOWN_ID || subject == record[0])
								&& (predicate == UNKNOWN_ID || predicate == record[1])
								&& (object == UNKNOWN_ID || object == record[2])
								&& (context == UNKNOWN_ID || context == record[3])) {
							recordReads++;
							if (record[1] == EDGE) {
								edgeReads++;
							}
							return record;
						}
					}
					return null;
				}

				@Override
				public void close() {
					if (!closed) {
						closed = true;
						closes++;
					}
				}
			};
		}

		@Override
		public long idOf(Value value) {
			return UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) {
			return SimpleValueFactory.getInstance().createIRI("urn:nested-exists-mode:" + id);
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public long count(long subject, long predicate, long object, long context) {
			throw new AssertionError("the witness must consume its real record cursors");
		}

		@Override
		public boolean has(long subject, long predicate, long object, long context) {
			assertThat(predicate).isEqualTo(FLAG);
			flagTests++;
			for (long[] record : records) {
				if ((subject == UNKNOWN_ID || subject == record[0])
						&& (predicate == UNKNOWN_ID || predicate == record[1])
						&& (object == UNKNOWN_ID || object == record[2])
						&& (context == UNKNOWN_ID || context == record[3])) {
					return true;
				}
			}
			return false;
		}

		@Override
		public double estimate(long subject, long predicate, long object, long context) {
			return predicate == EDGE ? INPUT_ROWS : predicate == FLAG ? FLAG_ROWS : 1D;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}
	}
}
